tab_plate:"方板", tab_disc:"土星", tab_globe:"球面", tab_hyper:"超球面",
lbl_pitch:"音高", lbl_note:"音名", lbl_mode:"模式", lbl_grains:"沙粒",
ctl_scale:"尺度", ctl_grains:"沙粒", ctl_settle:"沉降", ctl_spin:"旋转",
